#!/bin/sh

# Define the path to where your real Secrets.swift usually lives
SECRETS_FILE_PATH="../ftcScoutApp/Secrets.swift"

echo "Checking for Secrets.swift..."

# Xcode Cloud won't have the file because it's in .gitignore
if [ ! -f "$SECRETS_FILE_PATH" ]; then
    echo "Secrets.swift not found. Generating a mock file for Xcode Cloud tests."
    
    cat << EOF > "$SECRETS_FILE_PATH"
// Automatically generated by Xcode Cloud post-clone script.
// This prevents compile errors during automated testing.
enum Secrets {
    static let apiKey = "" //Enter api key here
}
EOF
    echo "Mock Secrets.swift successfully created!"
else
    echo "Secrets.swift already exists. Skipping generation."
fi